base as (
    select
           waybill_no ,
           max(bar_opr_code) bar_opr_code,
           max(oper_time) oper_time
    from analysis_services.fvp_${OPCODE} a
    where 1 = 1
      AND a.oper_dt >= '${STARTDATE}'
      AND a.oper_dt < '${ENDDATE}'
      AND a.oper_time >= '${STARTDATE}'
      AND a.oper_time < '${ENDDATE}'
      and a.waybill_no >= '1'
      and a.waybill_no < '5'
      and a.fzone_code = 'DC1'
      group by 1
) select oper_time::date tanggal,
         bar_opr_code nik,
         b.name nama,
         b.position_name jabatan,
         TO_CHAR(oper_time, 'HH24') || '.00 - ' || TO_CHAR(oper_time + INTERVAL '1 hour', 'HH24') || '.00'    as hour,
    ${OPCODE} opcode,
         count(*)  as total
    from base
    LEFT join analysis_services.tb_mv_tb_res_user b on bar_opr_code = b.loginid
    where 1=1 and (bar_opr_code in (select * from nik_dummy) or position_name = 'SORTER DC')
group by 1,2,3,4,5